from collections import deque


def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0]) if grid else 0
    seen = set()

    # Treat each separate 5-shaped frame independently.
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 5 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 5 and (ny,nx) not in seen:
                        seen.add((ny,nx))
                        q.append((ny,nx))

            r0 = min(y for y, _ in cells)
            r1 = max(y for y, _ in cells)
            c0 = min(x for _, x in cells)
            c1 = max(x for _, x in cells)
            top_cols = {x for y, x in cells if y == r0}
            gaps = [x for x in range(c0 + 1, c1) if x not in top_cols]
            if len(gaps) != 1:
                continue
            gap = gaps[0]

            # Fill the hollow body and close its top opening in blue (2).
            out[r0][gap] = 2
            for y in range(r0 + 1, r1):
                for x in range(c0 + 1, c1):
                    if grid[y][x] == 0:
                        out[y][x] = 2

            # Extend a ray from the opening across the row immediately above the frame.
            if r0 > 0:
                frame_mid = (c0 + c1) / 2
                direction = -1 if gap > frame_mid else 1
                x = gap
                while 0 <= x < w:
                    out[r0 - 1][x] = 2
                    x += direction

    return out
